import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import BackButton from '@/components/BackButton'
import type { Comment, Post } from '@/lib/types'

// Params not returned by generateStaticParams are rendered on demand,
// like getStaticPaths with `fallback: 'blocking'`.
export const dynamicParams = true

interface PostData {
  post: Post
  comments: Comment[]
}

export async function generateStaticParams(): Promise<Array<{ id: string }>> {
  const posts: Post[] = await fetch(
    'https://jsonplaceholder.typicode.com/posts'
  ).then((res) => res.json())

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }))
}

async function getPostData(id: string): Promise<PostData | null> {
  try {
    // Cached and revalidated every 5 minutes, like getStaticProps with `revalidate: 300`.
    const [postRes, commentsRes] = await Promise.all([
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
        next: { revalidate: 300 },
      }),
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`, {
        next: { revalidate: 300 },
      }),
    ])

    if (!postRes.ok || !commentsRes.ok) {
      return null
    }

    const post: Post = await postRes.json()
    const comments: Comment[] = await commentsRes.json()

    if (!post.id) {
      return null
    }

    return { post, comments }
  } catch {
    return null
  }
}

export async function generateMetadata({
  params,
}: {
  params: Promise<{ id: string }>
}): Promise<Metadata> {
  const { id } = await params
  const data = await getPostData(id)

  if (!data) {
    return {
      title: 'Post Not Found - My Blog',
    }
  }

  const description = data.post.body.substring(0, 160)

  return {
    title: `${data.post.title} - My Blog`,
    description,
    openGraph: {
      title: data.post.title,
      description,
    },
  }
}

export default async function BlogPost({
  params,
}: {
  params: Promise<{ id: string }>
}) {
  const { id } = await params
  const data = await getPostData(id)

  if (!data) {
    notFound()
  }

  const { post, comments } = data

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

